css:
.fc__h { margin: 0 0 .7rem; font-family: var(--os-font-body); font-weight: 700; font-size: 1.15rem; line-height: 1.08; color: var(--os-color-heading); }
.fc__t { line-height: 1.65; font-size: 1.02rem; color: var(--os-color-heading); }
.fc__t p { margin: 0; }
.fc__t br { display: block; content: ''; margin-top: .36rem; }
.fc__t a { color: var(--os-color-heading); text-decoration: underline; text-underline-offset: auto; }
.fc__t--s { font-size: .95rem; line-height: 1.6; color: var(--os-color-text-muted); margin-bottom: 1rem; }
